<?php

declare(strict_types=1);

namespace MailjetSDK\DTOs;

final class NewListrecipient extends \MailjetSDK\DTOs\Base\Listrecipient
{
    public const array REQUIRED_FIELDS = [
    'ContactID',
    'ListID',
];

    /**
     * The email address of the contact the list recipient is linked to. Interchangeable with `ContactID`.
     */
    public string $ContactAlt;
    /**
     * Unique numeric ID for the contact the list recipient is linked to. Interchangeable with `ContactAlt`.
     */
    public int $ContactID;
    /**
     * A unique contact list email address generated by Mailjet, for which to create the new recipient. Interchangeable with `ListID`.
     */
    public string $ListAlt;
    /**
     * Unique numeric ID of the contact list, for which to create the new recipient. Interchangeable with `ListAlt`.
     */
    public int $ListID;

    protected function assignMember(string $name, mixed $value): void
    {
        match ($name) {
            'ContactAlt' => is_string($value) ? $this->ContactAlt = $value : parent::assignMember($name, $value),
            'ContactID' => is_int($value) ? $this->ContactID = $value : parent::assignMember($name, $value),
            'ListAlt' => is_string($value) ? $this->ListAlt = $value : parent::assignMember($name, $value),
            'ListID' => is_int($value) ? $this->ListID = $value : parent::assignMember($name, $value),
            default => parent::assignMember($name, $value),
        };
    }
}
